const EVOLUTION_URL = 'http://rk-evolution:8080/message/sendText/construdata-felipe';
const EVOLUTION_API_KEY = 'construdata2026';

const diretores = [
  { nome: "Luiz Fernando", telefone: "5537999425397" },
  { nome: "Felipe Nery", telefone: "5561981846325" }
];

const financeiros = [
  { nome: "Renato", telefone: "5528999154319" },
  { nome: "Emilly Anjos", telefone: "5513974168911" }
];

const hoje = new Date();
const diaSemana = ['Domingo','Segunda','Terça','Quarta','Quinta','Sexta','Sábado'][hoje.getDay()];
const dataFormatada = hoje.toLocaleDateString('pt-BR');

const msgDiretor = `👷 *BOM DIA DIRETOR!*\n📅 ${diaSemana}, ${dataFormatada}\n\n📋 *TAREFAS DO DIA:*\n1. Delegar tarefas para equipes de campo\n2. Revisar RDOs pendentes\n3. Aprovar medições em aberto\n4. Acompanhar prazos críticos\n\n🔗 https://construdatamaxv2-clean.vercel.app/app/delegar-tarefas\n\n⚠️ _Não esqueça de delegar antes das 8h!_`;

const msgFinanceiro = `💰 *BOM DIA FINANCEIRO!*\n📅 ${diaSemana}, ${dataFormatada}\n\n📋 *TAREFAS DO DIA:*\n1. Registrar pagamentos realizados ontem\n2. Conciliar extratos bancários\n3. Atualizar fluxo de caixa\n4. Enviar comprovantes pendentes\n\n🔗 https://construdatamaxv2-clean.vercel.app/app/dre-financeiro\n\n⚠️ _Registre todos os pagamentos do dia anterior!_`;

// Função de Fetch assíncrono interno no n8n
const fetchApi = async (url, options) => {
     const axios = require('axios');
     try {
         const res = await axios(url, options);
         return res.data;
     } catch (err) {
         console.error('Fetch error:', err.message);
         return null;
     }
};

const results = [];

// 1. Enviar para Diretores
for (const d of diretores) {
    await fetchApi(EVOLUTION_URL, {
        method: 'POST',
        headers: {
            'apikey': EVOLUTION_API_KEY,
            'Content-Type': 'application/json'
        },
        data: {
            number: d.telefone,
            textMessage: { text: msgDiretor }
        }
    });
    results.push({ json: { tipo: 'diretor', nome: d.nome, enviado: true } });
}

// 2. Enviar para Financeiro
for (const f of financeiros) {
    await fetchApi(EVOLUTION_URL, {
        method: 'POST',
        headers: {
            'apikey': EVOLUTION_API_KEY,
            'Content-Type': 'application/json'
        },
        data: {
            number: f.telefone,
            textMessage: { text: msgFinanceiro }
        }
    });
    results.push({ json: { tipo: 'financeiro', nome: f.nome, enviado: true } });
}

return results;
